reference_solution:
def k_subarray_powers(nums,k):
    run=1;answer=[]
    for index,value in enumerate(nums):
        if index and value==nums[index-1]+1:run+=1
        else:run=1
        if index>=k-1:answer.append(value if run>=k else -1)
    return answer

